VALUES (17111, 'tt0440803', NULL, 'Shutter', 'ชัตเตอร์ กดติดวิญญาณ', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/7Tq7SrB14r3WpjJQOldbDHQk89J.jpg', 'https://image.tmdb.org/t/p/original/cX48taTcXP2oGXPvka8QFa4f4Qb.jpg', 'When Jane and Tun run over a girl in a car accident, they speed away immediately from the crime scene. However, Tun, a photographer, soon discovers strange shadows in his photos, which unsettles them.', NULL, NULL, 4.9403, 7.318, 0, 1.2373333333333333e+01, '2026-08-28 09:15:02', '2026-11-28 13:08:40')
